import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

export type CollapsiblePart = "root" | "trigger" | "indicator" | "content";

export const anatomy: Anatomy<CollapsiblePart> = createAnatomy("collapsible").parts(
  "root",
  "trigger",
  "indicator",
  "content",
);

export const parts: Record<CollapsiblePart, AnatomyPart> = anatomy.build();

/**
 * Pure, DOM-free, replayable on a server. Every handler checks
 * `defaultPrevented` first, which is what makes a consumer's own handler able
 * to veto the machine (merged ahead of ours by `mergeProps`).
 *
 * Enter and Space are the native behaviour of the `<button>` — no onKeyDown
 * anywhere, the platform does the APG split (Enter on keydown, Space on keyup)
 * better than a handler would.
 */

import { ariaAttr, boolAttr, dataAttr } from "../../dom/attrs";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { isFocusVisibleModality } from "../../nav";
import { parts } from "./collapsible.anatomy";
import { getContentId, getIndicatorId, getRootId, getTriggerId } from "./collapsible.dom";
import type { CollapsibleApi, CollapsibleSchema } from "./collapsible.types";

export function connect<T extends PropTypes>(
  service: Service<CollapsibleSchema>,
  normalize: NormalizeProps<T>,
): CollapsibleApi<T> {
  const { context, prop, send, scope } = service;

  const open = context.get("open");
  const disabled = prop("disabled");
  const keepMounted = prop("keepMounted");
  const dir = prop("dir");
  const state = open ? "open" : "closed";

  const focusSource = context.get("focusSource");
  const focusVisible = focusSource !== null && isFocusVisibleModality(focusSource);

  return {
    open,
    disabled,
    focusSource,
    focusVisible,

    setOpen(next: boolean): void {
      send({ type: "OPEN.SET", open: next });
    },
    toggle(): void {
      send({ type: "TRIGGER.CLICK" });
    },

    getRootProps: (): T["element"] =>
      normalize.element({
        ...parts.root.attrs,
        id: getRootId(scope),
        dir,
        "data-state": state,
        "data-disabled": dataAttr(disabled),
      }),

    getTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.trigger.attrs,
        id: getTriggerId(scope),
        type: "button",
        // Native `disabled` rather than `aria-disabled`: a disclosure trigger
        // has no reason to stay focusable while inert.
        disabled,
        "aria-expanded": boolAttr(open),
        // Only while the content is actually in the document — a dangling
        // IDREF names nothing (the popover's rule). Without `keepMounted` a
        // closed content is unmounted by the adapter's presence path.
        "aria-controls": open || keepMounted ? getContentId(scope) : undefined,
        "data-state": state,
        "data-disabled": dataAttr(disabled),
        "data-focus-visible": dataAttr(focusVisible),
        "data-focus-source": focusSource ?? undefined,
        onClick(event) {
          if (event.defaultPrevented || disabled) return;
          send({ type: "TRIGGER.CLICK" });
        },
        onFocus(event) {
          if (event.defaultPrevented) return;
          send({ type: "TRIGGER.FOCUS" });
        },
        onBlur(event) {
          if (event.defaultPrevented) return;
          send({ type: "TRIGGER.BLUR" });
        },
      }),

    getIndicatorProps: (): T["element"] =>
      normalize.element({
        ...parts.indicator.attrs,
        id: getIndicatorId(scope),
        // The trigger already carries the state; the chevron is decoration.
        "aria-hidden": ariaAttr(true),
        "data-state": state,
        "data-disabled": dataAttr(disabled),
      }),

    getContentProps: (): T["element"] =>
      normalize.element({
        ...parts.content.attrs,
        id: getContentId(scope),
        dir,
        // Only in `keepMounted` mode. Without it the content is unmounted by
        // the adapter's presence path, and `hidden` would kill its exit
        // animation (the tabs rule).
        hidden: !open && keepMounted ? true : undefined,
        // While the exit runs the content is still in the tree, already announced
        // collapsed: out of the tab order and the a11y tree until it is unmounted.
        inert: !open && !keepMounted ? true : undefined,
        "data-state": state,
        "data-disabled": dataAttr(disabled),
        // Until the first real toggle: a `defaultOpen` first paint must be
        // there, not arrive — the sheet answers with `animation: none`.
        "data-immediate": dataAttr(!context.get("animated")),
      }),
  };
}

import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

const COMPONENT = "collapsible";

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "trigger");
}

export function getIndicatorId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "indicator");
}

export function getContentId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "content");
}

export function getRootEl(scope: Scope): HTMLElement | null {
  return scope.getById(getRootId(scope));
}

export function getTriggerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getTriggerId(scope));
}

export function getContentEl(scope: Scope): HTMLElement | null {
  return scope.getById(getContentId(scope));
}

/**
 * The APG Disclosure primitive: a toggle plus one measurement.
 *
 * `open` is the single source of truth and the state is a projection of it —
 * the popover's two structural decisions, kept. The projection is what earns
 * this component a machine at all: the height measurement has to run when the
 * DOM already agrees with the value, and "an adapter updates the DOM BEFORE
 * playing its watch" (architecture.md) makes `watch → OPEN.SYNC → entry` the
 * one path where `content` is guaranteed to exist and to carry its new
 * `data-state` at the moment it is measured.
 *
 * `syncSize` writes `--sui-collapsible-height`/`--sui-collapsible-width`
 * straight onto the node rather than through a bindable — the same trade
 * `--sui-transform-origin` and `data-scroll` make: a measurement no state
 * depends on must not cost a transition, a notify and an adapter render. At
 * rest the content is `block-size: auto` (the variables feed only the
 * enter/exit keyframes), so growing content — streamed text, a nested
 * collapsible — follows on its own, which is also why there is deliberately no
 * ResizeObserver: an observer on a box whose `block-size` the sheet animates
 * would be a feedback loop, and the variables only need to be right at the two
 * boundaries, where `syncSize` is replayed every time.
 */

import { contains } from "../../dom/query";
import { restoreFocus } from "../../focus/restore-focus";
import { createMachine } from "../../machine/create-machine";
import type { Machine } from "../../machine/types";
import { getInputModality, trackInputModality } from "../../nav";
import type { InputModality } from "../../types";
import { getContentEl, getTriggerEl } from "./collapsible.dom";
import type { CollapsibleSchema } from "./collapsible.types";

export const machine: Machine<CollapsibleSchema> = createMachine<CollapsibleSchema>({
  props({ props }) {
    return { defaultOpen: false, disabled: false, keepMounted: false, ...props };
  },

  context({ prop, bindable }) {
    return {
      open: bindable<boolean>(() => ({
        defaultValue: prop("defaultOpen"),
        value: prop("open"),
        onChange: (open) => prop("onOpenChange")?.({ open }),
        debugLabel: "collapsible open",
      })),
      focusSource: bindable<InputModality | null>(() => ({ defaultValue: null })),
      animated: bindable<boolean>(() => ({ defaultValue: false })),
    };
  },

  initialState({ prop }) {
    return (prop("open") ?? prop("defaultOpen")) ? "open" : "closed";
  },

  effects: ["trackModality"],

  watch({ context, track, send }) {
    track(
      () => [context.get("open")],
      () => send({ type: "OPEN.SYNC" }),
    );
  },

  on: {
    "TRIGGER.CLICK": { guard: "isEnabled", actions: ["toggleOpen"] },
    // Deliberately unguarded: `disabled` disables the trigger, not the API.
    "OPEN.SET": { actions: ["setOpen"] },
    // `markAnimated` lives here and nowhere else: OPEN.SYNC only fires on a
    // *change* of `open` after `start()`, so the first render never lifts the
    // latch — a `defaultOpen` page load plays no entry animation.
    "OPEN.SYNC": [
      { guard: "isOpen", target: "open", actions: ["markAnimated"] },
      { target: "closed", actions: ["markAnimated"] },
    ],
    "TRIGGER.FOCUS": { actions: ["captureFocusSource"] },
    "TRIGGER.BLUR": { actions: ["clearFocusSource"] },
  },

  // `start()` plays the entry of the initial state, and the adapters start the
  // service after the DOM commit — a `defaultOpen` content is measured at
  // mount, on a node that exists.
  states: {
    open: { entry: ["syncSize"] },
    // The commit has already made the content inert or hidden, or (motion
    // `none`) scheduled its unmount; the focus inside it is still there to read.
    closed: { entry: ["returnFocus", "syncSize"] },
  },

  implementations: {
    guards: {
      isEnabled: ({ prop }) => !prop("disabled"),
      isOpen: ({ context }) => context.get("open"),
    },

    actions: {
      toggleOpen({ context }) {
        context.set("open", (open) => !open);
      },

      setOpen({ context, event }) {
        if (event.type === "OPEN.SET") context.set("open", event.open);
      },

      markAnimated({ context }) {
        context.set("animated", true);
      },

      captureFocusSource({ context, scope }) {
        // The default rather than a throw when no document exists — the same
        // answer `getInputModality` gives while nothing is tracking.
        context.set(
          "focusSource",
          scope.getRootNode() === null ? "pointer" : getInputModality(scope.getDoc()),
        );
      },

      clearFocusSource({ context }) {
        context.set("focusSource", null);
      },

      // A focus left inside a content that is closing would fall to `body` when
      // it unmounts or hides; a focus anywhere else was put there by someone. A
      // trigger disabled while open takes nothing, so `restoreFocus` falls back
      // on its neighbour (R61).
      returnFocus({ scope }) {
        const content = getContentEl(scope);
        if (content === null || !contains(content, scope.getActiveElement())) return;
        restoreFocus(getTriggerEl(scope), content);
      },

      /**
       * The heart of the component. DOM in an action, through `scope`, is the
       * popover's own precedent (`captureFinalFocus`); no document, no node —
       * no-op, which is what a server render needs.
       */
      syncSize({ scope }) {
        const content = getContentEl(scope);
        // `hidden` is keepMounted-closed: `display: none`, a zero rect —
        // nothing to measure.
        if (content === null || content.hidden) return;
        const { style } = content;
        const animation = style.animationName;
        const transition = style.transitionDuration;
        // Suspend the motion to read the size at rest: entering `closed`, the
        // exit animation is already applied at t=0 and would freeze the
        // measurement on the previous variable.
        style.animationName = "none";
        style.transitionDuration = "0s";
        const rect = content.getBoundingClientRect();
        style.setProperty("--sui-collapsible-height", `${rect.height}px`);
        style.setProperty("--sui-collapsible-width", `${rect.width}px`);
        style.animationName = animation;
        style.transitionDuration = transition;
      },
    },

    effects: {
      // No listener: the source is read once, when the focus lands. Holding the
      // handle is the whole job — the tracker has to be running before the
      // first Tab. Guarded like the popover's, because the unit project starts
      // this service with no document in the room.
      trackModality({ scope }) {
        if (scope.getRootNode() === null) return;
        return trackInputModality(scope.getDoc());
      },
    },
  },
});

import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { Direction, InputModality } from "../../types";

export interface CollapsibleOpenChangeDetails {
  readonly open: boolean;
}

export interface CollapsibleMachineProps {
  readonly dir?: Direction | undefined;
  /** Controlled: present means the consumer owns the value. */
  readonly open?: boolean | undefined;
  readonly defaultOpen?: boolean | undefined;
  /**
   * Disables the trigger, not the collapsible: a programmatic `setOpen` still
   * lands — the popover's rule, kept.
   */
  readonly disabled?: boolean | undefined;
  /**
   * Closed content stays mounted, `hidden`. That gives up the exit animation —
   * `display: none` runs none — which is the doctrine tabs established.
   */
  readonly keepMounted?: boolean | undefined;
  readonly onOpenChange?: ((details: CollapsibleOpenChangeDetails) => void) | undefined;
}

/** What the machine sees once the defaults are applied. */
export interface ResolvedCollapsibleMachineProps extends CollapsibleMachineProps {
  readonly defaultOpen: boolean;
  readonly disabled: boolean;
  readonly keepMounted: boolean;
}

export interface CollapsibleSchema extends MachineSchema {
  state: "open" | "closed";
  props: ResolvedCollapsibleMachineProps;
  /**
   * `open` is the single source of truth — the state is a projection of it, the
   * popover's shape. `focusSource` is the modality focus arrived under, held
   * until focus leaves (see `toggle`). `animated` is a latch: `false` until the
   * first open/close transition after `start()`, and it drives `data-immediate`
   * — a `defaultOpen` first paint must be there, not arrive.
   */
  context: {
    open: boolean;
    focusSource: InputModality | null;
    animated: boolean;
  };
  event:
    | { type: "TRIGGER.CLICK" }
    | { type: "TRIGGER.FOCUS" }
    | { type: "TRIGGER.BLUR" }
    | { type: "OPEN.SET"; open: boolean }
    | { type: "OPEN.SYNC" };
  action:
    | "toggleOpen"
    | "setOpen"
    | "syncSize"
    | "returnFocus"
    | "markAnimated"
    | "captureFocusSource"
    | "clearFocusSource";
  guard: "isEnabled" | "isOpen";
  effect: "trackModality";
}

export interface CollapsibleApi<T extends PropTypes = PropTypes> {
  readonly open: boolean;
  readonly disabled: boolean;
  /** The modality focus arrived under, or `null` while the trigger is not focused. */
  readonly focusSource: InputModality | null;
  /** True only while focused, and only when that source warrants a ring. */
  readonly focusVisible: boolean;
  /** Unguarded on purpose: `disabled` disables the trigger, not the API. */
  setOpen(open: boolean): void;
  /** The trigger's own path — respects `disabled`. */
  toggle(): void;
  getRootProps(): T["element"];
  getTriggerProps(): T["button"];
  getIndicatorProps(): T["element"];
  getContentProps(): T["element"];
}

export { anatomy, type CollapsiblePart, parts } from "./collapsible.anatomy";
export { connect } from "./collapsible.connect";
export {
  getContentEl,
  getContentId,
  getIndicatorId,
  getRootEl,
  getRootId,
  getTriggerEl,
  getTriggerId,
} from "./collapsible.dom";
export { machine } from "./collapsible.machine";
export type {
  CollapsibleApi,
  CollapsibleMachineProps,
  CollapsibleOpenChangeDetails,
  CollapsibleSchema,
  ResolvedCollapsibleMachineProps,
} from "./collapsible.types";

/**
 * The disclosure in React: one machine in the root, and one content that has to
 * be allowed to finish leaving.
 *
 * The adapter owns exactly one decision the core cannot make — whether the
 * content is in the tree at all — and it is the decision the whole component
 * turns on. React commits the DOM before it runs a layout effect, and
 * `useMachine` runs its watchers in one; that ordering is what lets the machine
 * measure a node that already carries its new `data-state`. Mount the content
 * later than the commit, or hide it earlier, and the measurement reads a box
 * that is not the one about to animate.
 *
 * `keepMounted` and the presence are the tabs arrangement, not a new one: a
 * kept content is `hidden` the moment it closes, `display: none` runs no
 * animation, and a presence left waiting on one would only schedule a render
 * nobody reads. `reduced` is deliberately not in that list — it keeps the 150ms
 * fade the sheet holds on purpose, and only `none` removes it.
 */

import * as collapsible from "@standarui/core/collapsible";
import { type ReactNode, type Ref, useMemo } from "react";
import { composeRefs } from "../../compose-refs";
import { createPart, type PartProps } from "../../create-part";
import { useEnvironment } from "../../environment";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { usePresence } from "../../presence";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type CollapsibleApi = collapsible.CollapsibleApi<ReactPropTypes>;

export interface UseCollapsibleProps
  extends collapsible.CollapsibleMachineProps,
    MachineRuntimeProps {}

interface CollapsibleContextValue {
  readonly api: CollapsibleApi;
  /**
   * Mirrored out of the machine props rather than read back off the api: the
   * content is what acts on it, and `connect` already spends it on `hidden`.
   * Only the mount decision is left, and that one is React's.
   */
  readonly keepMounted: boolean;
}

const CollapsibleContext = createPartContext<CollapsibleContextValue>("Collapsible");

export function useCollapsible(props: UseCollapsibleProps): CollapsibleApi {
  return collapsible.connect(useMachine(collapsible.machine, props), normalizeProps);
}

/** The api of the disclosure a subtree sits in — a consumer's own chrome reads it. */
export function useCollapsibleContext(): CollapsibleApi {
  return CollapsibleContext.usePart("CollapsibleContext").api;
}

const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "open",
  "defaultOpen",
  "disabled",
  "keepMounted",
  "onOpenChange",
] as const;

export interface CollapsibleRootProps
  extends UseCollapsibleProps,
    PartProps<"div", UseCollapsibleProps> {}

export function CollapsibleRoot(props: CollapsibleRootProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;
  const api = useCollapsible(machineProps);

  const context: CollapsibleContextValue = {
    api,
    keepMounted: machineProps.keepMounted === true,
  };

  return (
    <CollapsibleContext.Provider value={context}>
      {useRender({
        render,
        asChild,
        element: "div",
        props: api.getRootProps(),
        elementProps,
        children,
      })}
    </CollapsibleContext.Provider>
  );
}

export const CollapsibleTrigger: (props: PartProps<"button">) => ReactNode = createPart(
  CollapsibleContext,
  {
    name: "CollapsibleTrigger",
    element: "button",
    props: (context) => context.api.getTriggerProps(),
  },
);

/**
 * Decoration, and `aria-hidden` says so. A chevron composed into it rotates with
 * the box; an empty one is drawn by the sheet, so a consumer who wants the
 * library's own affordance writes nothing at all.
 */
export const CollapsibleIndicator: (props: PartProps<"span">) => ReactNode = createPart(
  CollapsibleContext,
  {
    name: "CollapsibleIndicator",
    element: "span",
    props: (context) => context.api.getIndicatorProps(),
  },
);

export function CollapsibleContent(props: PartProps<"div">): ReactNode {
  const { render, asChild, children, ref, ...elementProps } = props;
  const { api, keepMounted } = CollapsibleContext.usePart("CollapsibleContent");
  const { motion } = useEnvironment();

  const presence = usePresence({
    present: api.open,
    immediate: motion === "none" || keepMounted,
  });
  // Memoised on identity: a fresh callback every render would make React detach
  // and re-attach the consumer's own ref on every render too.
  const composed: Ref<HTMLElement> = useMemo(
    () => composeRefs(presence.ref, ref),
    [presence.ref, ref],
  );

  const element = useRender({
    render,
    asChild,
    element: "div",
    props: api.getContentProps(),
    elementProps: { ...elementProps, ref: composed },
    children,
  });

  // Read off the machine in the opening direction and off the presence only in
  // the closing one: the entry action that measures this node runs in the layout
  // effect of the very commit that opened it, and it looks the node up by id.
  // The presence never delays a mount, it only extends one past the close.
  return keepMounted || api.open || presence.present ? element : null;
}

/**
 * `<Collapsible label="…">…</Collapsible>` — four nodes, no collection, and the
 * layer's clearest case of a composed form that already existed in the wild.
 *
 * The documentation site had written this exact function by hand
 * (`apps/docs/demos/collapsible-basic.tsx`, a local `Disclosure` taking a `label`
 * and children) before the composed layer reached this component. That is the
 * argument for the shape rather than a coincidence: when the only way to use the
 * parts is to first write the same four-node wrapper, the wrapper is the API.
 *
 * **`label` is required, and it is an accessibility fact rather than a taste.**
 * `CollapsibleTrigger` has no default accessible name — `getTriggerProps` writes
 * the `aria-expanded`/`aria-controls` pair and nothing that names the button. A
 * disclosure whose trigger is empty is a nameless button in the tab order, so the
 * name comes from the consumer or the part is not rendered, and there is no
 * useful disclosure without its trigger. Compare `checkbox`, where `label` is
 * optional because a `Field` above it can name the box through the native
 * `label[for]` the root already wires; nothing plays that role here.
 *
 * **The indicator is placed unconditionally**, and it is the one node here that
 * costs nothing to a consumer who does not want it. `getIndicatorProps` writes
 * `aria-hidden`, so it is never announced, and the sheet draws the chevron under
 * `:where(:empty)` — the same rule `checkbox` and `pagination` use — so an empty
 * span is the affordance rather than a placeholder for one. A consumer who wants
 * their own glyph puts it in `parts.indicator`, and the `:empty` guard steps
 * aside on its own.
 *
 * **`children` is the panel, not the root's slot.** What the root contains is the
 * two parts below, hardcoded; the consumer's children belong to the content. So
 * `children` is excluded from the root's props and re-declared for the panel,
 * exactly as `checkbox` excludes it outright.
 */

import type { ReactNode } from "react";
import type { PartProps } from "../../create-part";
import {
  CollapsibleContent,
  CollapsibleIndicator,
  CollapsibleRoot,
  CollapsibleTrigger,
  type UseCollapsibleProps,
} from "./collapsible";

/**
 * The escape hatch, applied **last** on every part: what the layer defaults is a
 * default, and the consumer's entry wins over it. No `Omit` of `id` or of the
 * IDREFs here, unlike the collections: each of these three parts is placed once,
 * so a fixed id is a fixed id and not the same one repeated down a list.
 */
export interface CollapsibleParts {
  readonly trigger?: PartProps<"button"> | undefined;
  readonly indicator?: PartProps<"span"> | undefined;
  readonly content?: PartProps<"div"> | undefined;
}

export interface CollapsibleComposedProps
  extends UseCollapsibleProps,
    Omit<PartProps<"div", UseCollapsibleProps>, "children"> {
  /** Names the trigger. Required — see above. */
  readonly label: ReactNode;
  /** The panel's content. */
  readonly children?: ReactNode;
  readonly parts?: CollapsibleParts | undefined;
}

export function Collapsible(props: CollapsibleComposedProps): ReactNode {
  const { label, children, parts, ...root } = props;

  return (
    <CollapsibleRoot {...root}>
      <CollapsibleTrigger {...parts?.trigger}>
        <CollapsibleIndicator {...parts?.indicator} />
        {label}
      </CollapsibleTrigger>
      <CollapsibleContent {...parts?.content}>{children}</CollapsibleContent>
    </CollapsibleRoot>
  );
}

export type {
  CollapsibleMachineProps,
  CollapsibleOpenChangeDetails,
} from "@standarui/core/collapsible";
export {
  type CollapsibleApi,
  CollapsibleContent,
  CollapsibleIndicator,
  CollapsibleRoot,
  type CollapsibleRootProps,
  CollapsibleTrigger,
  type UseCollapsibleProps,
  useCollapsible,
  useCollapsibleContext,
} from "./collapsible";
export {
  Collapsible,
  type CollapsibleComposedProps,
  type CollapsibleParts,
} from "./composed";
